    return List.generate(10, (index) {
      int num = index + 1;
      return {
        "q": "$num. سوال نمونه $num از $chapterTitle ($partTitle) 🔬",
        "options": [
          {"emoji": "✅", "text": "گزینه صحیح نمونه الف"},
          {"emoji": "❌", "text": "گزینه نادرست ب"},
